def cell_caption(condition, target_day="day15"):
    description = CONDITION_DESCRIPTIONS.get(condition, condition.replace("_", " "))
    day = str(target_day).replace("day", "")
    return f"A microscopic image of vascularized cardiac organoids {description}, observed on day {day}."
